import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"FD Cal — engineering audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/"}],["meta",{"property":"og:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/"}],["meta",{"name":"twitter:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/index.md","filePath":"audits/index.md","lastUpdated":1794184492000}`),a={name:`audits/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="fd-cal-—-engineering-audit" tabindex="-1">FD Cal — engineering audit <a class="header-anchor" href="#fd-cal-—-engineering-audit" aria-label="Permalink to “FD Cal — engineering audit”">​</a></h1><p><strong>Audit date:</strong> 8 November 2026<br><strong>Audited source:</strong> <code>dev</code> at <code>a455462a959f37db757970d0a3078a4d9a3ef028</code><br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">aaron-fredrick/RULESETS</a><br><strong>Status:</strong> Static engineering review with owner feedback incorporated. The implementation plan is documentation only; no application changes have been applied.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to “Reports”">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Coverage</th></tr></thead><tbody><tr><td><a href="./EXECUTIVE-SUMMARY.html">Executive summary</a></td><td>Priority-ranked findings, owner dispositions and remediation order</td></tr><tr><td><a href="./IMPLEMENTATION-PLAN.html">Implementation plan</a></td><td>Detailed analysis, implementation phases, acceptance criteria and non-regression guardrails</td></tr><tr><td><a href="./ENGINE-CORE.html">Engine and financial core</a></td><td>Dates, interest, FD cash flows, simulation lifecycle, balances and results</td></tr><tr><td><a href="./STRATEGIES-AND-SEARCH.html">Strategies and search</a></td><td>Greedy, GSS, Absolute R, Absolute R+, search budgets, parity and architecture</td></tr><tr><td><a href="./WEB-UI-UX-ACCESSIBILITY.html">Web UI, UX and accessibility</a></td><td>Form flows, responsive layout, motion, keyboard and screen-reader semantics</td></tr><tr><td><a href="./REPORTING-OUTPUTS.html">Reporting and outputs</a></td><td>In-app metrics, standalone HTML, ledger, charts and financial presentation</td></tr><tr><td><a href="./DATA-AND-FINANCIAL-ASSUMPTIONS.html">Data and financial assumptions</a></td><td>Catalogue quality, provenance, eligibility, fees, AIT and product constraints</td></tr><tr><td><a href="./SECURITY-PRIVACY.html">Security and privacy</a></td><td>Untrusted configuration, DOM rendering, local storage and client-side exposure</td></tr><tr><td><a href="./BUILD-DEPLOYMENT-AND-QUALITY.html">Build, deployment and quality</a></td><td>GitHub Actions, Pages composition, dev preview, tests and operational gaps</td></tr></tbody></table><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to “Method”">​</a></h2><p>The review applies the principles in the RULESETS repository, principally:</p><ul><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Coding" target="_blank" rel="noreferrer">Coding practices</a>: maintainability, modularity, API contracts, error handling, security boundaries, documentation and meaningful tests.</li><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/UI" target="_blank" rel="noreferrer">UI guidelines</a>: product-aware design, hierarchy, restraint, interaction, motion, responsive behaviour and rendered-state QA.</li><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Web" target="_blank" rel="noreferrer">Web engineering practices</a>: production standards, privacy, analytics, SEO, accessibility, performance and release readiness.</li></ul><p>This is a risk-based, subsystem-level source audit of the active JavaScript engine, strategy/search paths, browser UI, reporting, catalogue/configuration paths, CLI, build scripts, workflows and test inventory; it is not a line-by-line proof of every statement. It is not a formal verification, financial-product certification, penetration test, legal opinion, or complete external revalidation of every bank rate and fee. Browser screenshots, assistive-technology checks and live production/dev visual inspection remain separate verification tasks.</p><h2 id="severity" tabindex="-1">Severity <a class="header-anchor" href="#severity" aria-label="Permalink to “Severity”">​</a></h2><ul><li><strong>P1 — High:</strong> credible security exposure or materially misleading financial output. Address before broad use.</li><li><strong>P2 — Medium:</strong> correctness, runtime, data-trust or deployment risk with meaningful user impact.</li><li><strong>P3 — Low:</strong> accessibility, maintainability, observability or test-quality improvement; schedule after higher-risk work.</li></ul><p>Each finding includes evidence, impact, and a concrete recommendation. A finding marked <em>assumption to confirm</em> should be resolved against bank/product terms before changing the model.</p><h2 id="verification-boundary" tabindex="-1">Verification boundary <a class="header-anchor" href="#verification-boundary" aria-label="Permalink to “Verification boundary”">​</a></h2><p>The Node.js test workflow passed on the audited dev revision <code>a455462a959f37db757970d0a3078a4d9a3ef028</code> (run <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42509949387" target="_blank" rel="noreferrer">42509949387</a>). The audit did not include a manual browser or screen-reader session. Deployment status is tracked separately from source-level findings.</p><h2 id="planning-status" tabindex="-1">Planning status <a class="header-anchor" href="#planning-status" aria-label="Permalink to “Planning status”">​</a></h2><p>Owner feedback has been recorded in the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a>. SEC-01 and FIN-01 are accepted P1 work; SEARCH-01, DATA-01 and DEPLOY-01 are accepted workstreams. ENG-01 requires product-term clarification before changing payout dates; ENG-02 retains the current elapsed-day convention pending source verification. DATA-02 is an intentional scope boundary. DATA-03 and QA-01 are deferred for owner decisions.</p><p>The audit branch remains report/plan-only. Implementation should proceed in focused branches from <code>dev</code>, with the plan&#39;s regression and non-regression gates.</p>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};